def _apply_process_priority(level):
    """Set this process's scheduling priority (child render processes inherit it).
    Cross-platform; silently no-ops if it can't. `level` is one of
    High / Above Normal / Normal / Below Normal / Low."""
    try:
        import os as _os
        if sys.platform.startswith("win"):
            import ctypes
            classes = {
                "High": 0x00000080, "Above Normal": 0x00008000,
                "Normal": 0x00000020, "Below Normal": 0x00004000,
                "Low": 0x00000040,                       # IDLE_PRIORITY_CLASS
            }
            cls = classes.get(level, 0x00000020)
            ctypes.windll.kernel32.SetPriorityClass(
                ctypes.windll.kernel32.GetCurrentProcess(), cls)
        else:
            # POSIX niceness: lower nice = higher priority
            nice = {"High": -10, "Above Normal": -5, "Normal": 0,
                    "Below Normal": 5, "Low": 10}.get(level, 0)
            try:
                _os.nice(nice - _os.nice(0))     # set absolute-ish niceness
            except Exception:
                pass
    except Exception:
        pass


_APP_ICON = None
_BLACK_COVER = None


def _safe_output_stem(title):
    """Turn a song title into a safe output-file stem (no extension).

    Replaces characters Windows forbids in filenames, and — importantly —
    strips a trailing BMS chart extension. Charts with no #TITLE fall back to
    their filename (e.g. 'song.bms'), so without this the exported file would
    be named 'song.bms.mkv' / 'song.bms.flac', which Windows Explorer shows as
    'song.bms' when 'hide known extensions' is on — looking like the render
    produced a .bms file. The render is fine; only the name was misleading.
    """
    safe = "".join("_" if c in '<>:"/\\|?*' else c for c in (title or "")).strip()
    if not safe:
        return "untitled"
    stem, ext = os.path.splitext(safe)
    if ext.lower() in bms_core.BMS_EXTS and stem:
        safe = stem
    return safe


def _black_cover_bytes():
    """JPEG bytes for a 1000x1000 black square (cached). A clean 'no real art' cover
    without writing any file — same as the Tk app's helper."""
    global _BLACK_COVER
    if _BLACK_COVER is None:
        try:
            from PIL import Image
            import io as _io
            buf = _io.BytesIO()
            Image.new("RGB", (1000, 1000), (0, 0, 0)).save(buf, format="JPEG", quality=85)
            _BLACK_COVER = buf.getvalue()
        except Exception:
            _BLACK_COVER = None
    return _BLACK_COVER


def _app_icon():
    """Build a multi-resolution QIcon from the embedded per-size PNGs (each pre-rendered
    crisply with a white outline) so Windows shows a sharp, visible icon at every size
    instead of squishing one big pixmap."""
    global _APP_ICON
    if _APP_ICON is not None:
        return _APP_ICON
    try:
        from PySide6.QtGui import QPixmap, QIcon
        import base64
        icon = QIcon()
        for sz, b64 in ICON_SIZES_B64.items():
            pm = QPixmap()
            pm.loadFromData(base64.b64decode(b64))
            if not pm.isNull():
                icon.addPixmap(pm)
        if icon.isNull():
            return None
        _APP_ICON = icon
        return icon
    except Exception:
        return None


def _numkey(v):
    """Numeric value of a notes/bpm field for sorting; non-numeric → 0."""
    try:
        return float(str(v))
    except (ValueError, TypeError):
        return 0.0


class CollapsibleAlbumView(QScrollArea):
    """Album grid split into collapsible level sections (Tables tab). Each level has a
    full-width header with a native disclosure triangle that toggles its tile grid.
    The vertical scrollbar is always reserved so collapsing never reflows tile width."""
    def __init__(self):
        super().__init__()
        self.setWidgetResizable(True)
        # keep the scrollbar slot always present so the usable width — and therefore
        # the number of tiles per row — never changes when a section collapses
        self.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOn)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self._inner = QWidget()
        self._vbox = QVBoxLayout(self._inner)
        self._vbox.setSpacing(0); self._vbox.setContentsMargins(0, 0, 0, 0)
        self.setWidget(self._inner)
        self._sections = []
        self._headers = []
        self._on_resize = None          # owner sets this to recompute grid heights

    def resizeEvent(self, e):
        super().resizeEvent(e)
        if self._on_resize is not None:
            self._on_resize()

    def clear_sections(self):
        self._headers = []
        while self._vbox.count():
            it = self._vbox.takeAt(0)
            if it.widget():
                it.widget().setParent(None)

    def add_section(self, label, count, grid):
        from PySide6.QtWidgets import QToolButton
        header = QToolButton()
        header.setText(f"  {label}    ({count})")
        header.setCheckable(True); header.setChecked(True)
        header.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
        header.setArrowType(Qt.DownArrow)          # native triangle, crisp at any DPI
        header.setStyleSheet(
            "QToolButton { border:none; background:transparent; font-weight:bold;"
            " padding:6px 4px; text-align:left; }"
            "QToolButton:hover { background:rgba(0,0,0,0.06); }")
        header.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        def toggle(checked, g=grid, h=header):
            g.setVisible(checked)
            h.setArrowType(Qt.DownArrow if checked else Qt.RightArrow)
        header.toggled.connect(toggle)
        self._headers.append(header)
        self._vbox.addWidget(header)
        self._vbox.addWidget(grid)

    def set_all_collapsed(self, collapsed):
        for h in self._headers:
            h.setChecked(not collapsed)

    def finish(self):
        self._vbox.addStretch(1)


class _NumericTreeItem(QTreeWidgetItem):
    """A QTreeWidgetItem that sorts numeric columns by VALUE, not by text. The default
    item compares column display strings lexicographically, so "1000" sorts before
    "200" — wrong for the BPM and Notes columns. When both cells parse as numbers we
    compare numerically; otherwise we fall back to a case-insensitive text compare.

    A column may also carry an explicit numeric SORT KEY in Qt.UserRole+2 (used by the
    playlist "Added" column, whose cell shows a human date like 2026-06-16 but must
    sort chronologically by the underlying timestamp). When both items provide that
    key for the active column, it wins over the text-based comparison."""
    SORTKEY_ROLE = Qt.UserRole + 2

    def __lt__(self, other):
        col = self.treeWidget().sortColumn() if self.treeWidget() else 0
        ka = self.data(col, self.SORTKEY_ROLE)
        kb = other.data(col, self.SORTKEY_ROLE)
        if ka is not None and kb is not None:
            try:
                return float(ka) < float(kb)
            except (ValueError, TypeError):
                pass
        a = self.text(col); b = other.text(col)
        try:
            return float(a.replace(",", "")) < float(b.replace(",", ""))
        except (ValueError, AttributeError):
            return a.casefold() < b.casefold()


class MarqueeLabel(QLabel):
    """A single-line label that horizontally scrolls its text when it's too wide,
    used for the now-playing title in the transport bar. Emits `clicked` when pressed
    so the now-playing title can act like a list selection."""
    clicked = Signal()

    def __init__(self, text=""):
        super().__init__()
        self._full = text
        self._offset = 0
        # no hardcoded colour — inherit the palette text colour so it's dark on a
        # light theme and white on a dark theme
        from PySide6.QtCore import QTimer
        self._timer = QTimer(self); self._timer.timeout.connect(self._scroll)

    def mousePressEvent(self, e):
        if self._full:
            self.clicked.emit()
        super().mousePressEvent(e)

    def enterEvent(self, e):
        # On hover, echo the now-playing entry highlight (blue + bold) so it reads as
        # clickable — but only when there's actually a song to click through to.
        if self._full:
            self.setStyleSheet("color: #2d7dff; font-weight: bold;")
        super().enterEvent(e)

    def leaveEvent(self, e):
        # restore the inherited palette colour / normal weight
        self.setStyleSheet("")
        super().leaveEvent(e)

    def setSong(self, text):
        self._full = text or ""
        self._offset = 0
        self.setText(self._full)
        # only present as clickable (hand cursor) when there's actually a title to
        # click through to; an empty now-playing field should feel inert.
        from PySide6.QtCore import Qt as _Qt
        self.setCursor(_Qt.PointingHandCursor if self._full else _Qt.ArrowCursor)
        self.setToolTip("Show info for the playing song" if self._full else "")
        if not self._full:
            self.setStyleSheet("")          # drop any lingering hover style
        if self._full and self.fontMetrics().horizontalAdvance(self._full) > self.width():
            self._timer.start(200)
        else:
            self._timer.stop()

    def _scroll(self):
        if not self._full:
            self._timer.stop(); return
        self._offset = (self._offset + 1) % (len(self._full) + 3)
        rot = self._full + "   " + self._full
        self.setText(rot[self._offset:self._offset + len(self._full)])


class MarqueeList(QListWidget):
    """Icon-mode list whose hovered item scrolls its full title when it's too long
    to fit — mirroring the Tk AlbumGrid marquee (rotate chars every 180ms, restore
    the elided text on leave). Each item stores its full label in Qt.UserRole+1."""
    FULL_ROLE = Qt.UserRole + 1
    VISIBLE_CHARS = 22                  # how many chars show in a tile line

    def __init__(self):
        super().__init__()
        self.setMouseTracking(True)
        from PySide6.QtCore import QTimer
        self._marquee_row = -1
        self._marquee_pos = 0
        self._marquee_timer = QTimer(self)
        self._marquee_timer.setInterval(180)
        self._marquee_timer.timeout.connect(self._marquee_step)

    def _display_for(self, full):
        # title line elided to VISIBLE_CHARS (artist, after newline, left as-is)
        if "\n" in full:
            title, rest = full.split("\n", 1); rest = "\n" + rest
        else:
            title, rest = full, ""
        if len(title) <= self.VISIBLE_CHARS:
            return full
        return title[:self.VISIBLE_CHARS - 1] + "\u2026" + rest

    def mouseMoveEvent(self, e):
        it = self.itemAt(e.pos())
        row = self.row(it) if it else -1
        if row != self._marquee_row:
            self._restore_marquee()
            self._marquee_row = row
            self._marquee_pos = 0
            if row >= 0:
                full = it.data(self.FULL_ROLE) or it.text()
                title = full.split("\n", 1)[0]
                if len(title) > self.VISIBLE_CHARS:
                    self._marquee_timer.start()
        super().mouseMoveEvent(e)

    def leaveEvent(self, e):
        self._restore_marquee(); self._marquee_row = -1
        super().leaveEvent(e)

    def _restore_marquee(self):
        self._marquee_timer.stop()
        if 0 <= self._marquee_row < self.count():
            it = self.item(self._marquee_row)
            if it:
                full = it.data(self.FULL_ROLE)
                if full is not None:
                    it.setText(self._display_for(full))

    def _marquee_step(self):
        if not (0 <= self._marquee_row < self.count()):
            self._marquee_timer.stop(); return
        it = self.item(self._marquee_row)
        if it is None:
            self._marquee_timer.stop(); return
        full = it.data(self.FULL_ROLE) or it.text()
        if "\n" in full:
            title, rest = full.split("\n", 1); rest = "\n" + rest
        else:
            title, rest = full, ""
        pad = title + "    "
        self._marquee_pos = (self._marquee_pos + 1) % len(pad)
        rolled = (pad[self._marquee_pos:] + pad[:self._marquee_pos])[:self.VISIBLE_CHARS]
        it.setText(rolled + rest)


def _make_moon_icon(size=18, color=(80, 80, 90)):
    """Crescent-moon icon (drawn by subtracting an offset circle from a full disc).
    Shown when the app is in LIGHT mode — clicking it switches to dark."""
    from PySide6.QtGui import QPixmap, QPainter, QColor, QBrush, QIcon, QPainterPath
    from PySide6.QtCore import QRectF, Qt as _Qt
    pm = QPixmap(size, size); pm.fill(_Qt.transparent)
    p = QPainter(pm); p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    full = QPainterPath(); full.addEllipse(QRectF(2, 2, size - 4, size - 4))
    bite = QPainterPath(); bite.addEllipse(QRectF(size * 0.42, 1, size - 4, size - 4))
    crescent = full.subtracted(bite)
    p.setPen(_Qt.NoPen); p.setBrush(QBrush(QColor(*color)))
    p.drawPath(crescent); p.end()
    return QIcon(pm)


def _make_sun_icon(size=18, color=(240, 200, 60)):
    """Sun icon (a disc with radiating rays). Shown when the app is in DARK mode —
    clicking it switches to light."""
    from PySide6.QtGui import QPixmap, QPainter, QColor, QBrush, QPen, QIcon
    from PySide6.QtCore import QPointF, Qt as _Qt
    import math
    pm = QPixmap(size, size); pm.fill(_Qt.transparent)
    p = QPainter(pm); p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    c = size / 2.0; r = size * 0.22
    p.setPen(_Qt.NoPen); p.setBrush(QBrush(QColor(*color)))
    p.drawEllipse(QPointF(c, c), r, r)
    p.setPen(QPen(QColor(*color), 1.6))
    for k in range(8):
        a = k * math.pi / 4
        r1, r2 = r + size * 0.10, r + size * 0.22
        p.drawLine(QPointF(c + r1 * math.cos(a), c + r1 * math.sin(a)),
                   QPointF(c + r2 * math.cos(a), c + r2 * math.sin(a)))
    p.end()
    return QIcon(pm)


def _make_queue_arrow_icon(size=18):
    """Draw the 'add to queue' icon: a white right-pointing triangle inside a filled
    green circle. Hand-drawn (not a system standardIcon) so it looks the same on every
    OS/theme — the Qt6 SP_ArrowForward standard icon is an ugly grey glyph that varies
    by platform. Returns a QIcon."""
    from PySide6.QtGui import QPixmap, QPainter, QColor, QBrush, QPen, QPolygonF, QIcon
    from PySide6.QtCore import QPointF, Qt as _Qt
    pm = QPixmap(size, size)
    pm.fill(_Qt.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    # green disc
    p.setPen(QPen(QColor(255, 255, 255), 0))
    p.setBrush(QBrush(QColor(63, 174, 80)))     # #3fae50, matches the BGA indicator green
    p.drawEllipse(1, 1, size - 2, size - 2)
    # white play-style triangle, centred, pointing right
    cx, cy = size / 2.0, size / 2.0
    r = size * 0.24
    tri = QPolygonF([QPointF(cx - r * 0.7, cy - r),
                     QPointF(cx - r * 0.7, cy + r),
                     QPointF(cx + r, cy)])
    p.setPen(_Qt.NoPen); p.setBrush(QBrush(QColor(255, 255, 255)))
    p.drawPolygon(tri)
    p.end()
    return QIcon(pm)


def _draw_playhead_caret(p, x, w, h):
    """Draw a high-visibility playhead marker at column x: a downward triangle capping
    the top, an upward triangle capping the bottom, and a vertical line joining their
    tips. Drawn in white with a thin dark outline so it stands out over any waveform
    colour or moodbar hue. Shared by WaveformBar and MoodbarBar for a consistent look."""
    from PySide6.QtGui import QColor, QPen, QPolygonF, QBrush, QPainter
    from PySide6.QtCore import QPointF
    x = int(max(0, min(w, x)))
    tw = 4          # half-width of the triangle caps
    th = 5          # height of each triangle
    # Enable antialiasing BEFORE drawing anything so the line and the triangles are
    # rasterised the same way — otherwise the aliased line snaps to the pixel grid and
    # appears shifted right of the antialiased triangle apex.
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    # Draw the connecting line at the pixel CENTER (x + 0.5) so it lines up exactly under
    # the triangle tips, which apex at x. A dark halo under a white core keeps it visible
    # over any waveform colour or moodbar hue.
    lx = x + 0.5
    p.setPen(QPen(QColor(0, 0, 0, 160), 3)); p.drawLine(QPointF(lx, 0), QPointF(lx, h))
    p.setPen(QPen(QColor(255, 255, 255), 1)); p.drawLine(QPointF(lx, 0), QPointF(lx, h))
    p.setPen(QPen(QColor(0, 0, 0, 200), 1))
    p.setBrush(QBrush(QColor(255, 255, 255)))
    # top cap: downward-pointing triangle (flat edge along the top), apex at the line
    top = QPolygonF([QPointF(lx - tw, 0), QPointF(lx + tw, 0), QPointF(lx, th)])
    # bottom cap: upward-pointing triangle (flat edge along the bottom)
    bot = QPolygonF([QPointF(lx - tw, h), QPointF(lx + tw, h), QPointF(lx, h - th)])
    p.drawPolygon(top); p.drawPolygon(bot)


class MoodbarBar(QWidget):
    """Moodbar-style seekbar: each vertical column is a colour derived from the audio's
    spectral content at that point in time (bass→red, mids→green, treble→blue), so the
    whole track reads as a colour signature. Played portion is full-opacity; the
    upcoming portion is dimmed. Same seek/scrub interface as WaveformBar (click/drag →
    `seek` fraction, `set_pos` moves the playhead), so it's a drop-in replacement.
    Inspired by the moodbar project (github.com/exaile/moodbar)."""
    seek = Signal(float)             # 0..1 fraction
    LINE = "#1a1a1a"

    def __init__(self):
        super().__init__()
        self._cols = []                  # list of (r,g,b) 0..255 per column
        self._pos = 0.0
        self._bright = None              # QPixmap: full-brightness bar (1px tall)
        self._dim = None                 # QPixmap: dimmed bar (upcoming portion)
        self.setMinimumWidth(200); self.setFixedHeight(30)

    def _build_pixmaps(self):
        """Pre-render the colour strip once (bright + dimmed) as 1px-tall pixmaps at the
        colour-list resolution. paintEvent then just scales/blits these — turning an
        O(width) Python loop every repaint into two C++ blits. Rebuilt only when the
        colour data changes, not per playhead tick."""
        from PySide6.QtGui import QPixmap, QImage
        n = len(self._cols)
        if n == 0:
            self._bright = self._dim = None; return
        imgB = QImage(n, 1, QImage.Format_RGB32)
        imgD = QImage(n, 1, QImage.Format_RGB32)
        for i, (r, g, b) in enumerate(self._cols):
            imgB.setPixel(i, 0, (0xFF << 24) | (r << 16) | (g << 8) | b)
            dr, dg, db = r * 55 // 100, g * 55 // 100, b * 55 // 100
            imgD.setPixel(i, 0, (0xFF << 24) | (dr << 16) | (dg << 8) | db)
        self._bright = QPixmap.fromImage(imgB)
        self._dim = QPixmap.fromImage(imgD)

    def set_colors(self, cols):
        self._cols = cols or []; self._pos = 0.0
        self._build_pixmaps(); self.update()

    def clear(self):
        """Blank the bar immediately (e.g. on song change, before the new moodbar is
        ready) so the previous song's colours don't linger."""
        self._cols = []; self._pos = 0.0
        self._bright = self._dim = None; self.update()

    # alias so callers can treat waveform/moodbar uniformly if desired
    def set_envelope(self, _env):
        pass

    def set_pos(self, frac):
        self._pos = max(0.0, min(1.0, frac)); self.update()

    def _frac(self, x):
        return max(0.0, min(1.0, x / max(1, self.width())))

    def mousePressEvent(self, e):
        self.seek.emit(self._frac(e.x()))

    def mouseMoveEvent(self, e):
        self.seek.emit(self._frac(e.x()))

    def paintEvent(self, _):
        from PySide6.QtGui import QPainter
        from PySide6.QtCore import QRect
        if self._bright is None:
            return
        p = QPainter(self)
        w, h = self.width(), self.height()
        played = int(self._pos * w)
        # Draw BOTH strips scaled to the FULL widget width — identical transform every
        # frame, so no wobble. The bright strip is simply clipped to the played region.
        # (Scaling a proportional sub-rect of the source per frame caused the playhead
        # jitter: the source-width rounding jumped unevenly as `played` advanced.)
        p.drawPixmap(QRect(0, 0, w, h), self._dim)
        if played > 0:
            p.save()
            p.setClipRect(QRect(0, 0, played, h))
            p.drawPixmap(QRect(0, 0, w, h), self._bright)
            p.restore()
        _draw_playhead_caret(p, played, w, h)


class SpectrogramBar(QWidget):
    """Spectrogram-strip seekbar: a 2D freq×time heat-map. X is time, Y is frequency
    (low at the bottom, high at the top), brightness/colour is energy — so you see the
    song's frequency LAYERS (kick on the bottom, hats/melody higher up) rather than the
    moodbar's single averaged colour per moment. Same seek/scrub interface as the other
    bars (click/drag → `seek`, `set_pos` moves the playhead), so it's a drop-in. The
    played portion is full-brightness; the upcoming portion is dimmed."""
    seek = Signal(float)             # 0..1 fraction

    def __init__(self):
        super().__init__()
        self._pos = 0.0
        self._bright = None              # QPixmap: full spectrogram (ncols × H)
        self._dim = None                 # QPixmap: dimmed copy
        self.setMinimumWidth(200); self.setFixedHeight(30)

    def set_image(self, rows):
        """rows: a 2D list/array shaped (H, ncols) of (r,g,b) — one row per frequency
        band (top = highest freq), one column per time slice. Pre-rendered to two
        pixmaps (bright + dimmed) so painting is a plain scaled blit. Built from a numpy
        buffer in one shot (not per-pixel) so it's a few ms even at 30×600."""
        from PySide6.QtGui import QPixmap, QImage
        if rows is None or len(rows) == 0 or len(rows[0]) == 0:
            self._bright = self._dim = None; self._pos = 0.0; self.update(); return
        try:
            import numpy as np
            arr = np.asarray(rows, dtype=np.uint8)          # (H, n, 3) RGB
            h, n = arr.shape[0], arr.shape[1]
            # QImage.Format_RGB32 is BGRA in memory; build a (H,n,4) buffer
            buf = np.empty((h, n, 4), np.uint8)
            buf[:, :, 0] = arr[:, :, 2]                     # B
            buf[:, :, 1] = arr[:, :, 1]                     # G
            buf[:, :, 2] = arr[:, :, 0]                     # R
            buf[:, :, 3] = 255
            imgB = QImage(buf.tobytes(), n, h, QImage.Format_RGB32)
            dim = (arr.astype(np.uint16) * 55 // 100).astype(np.uint8)
            bufd = np.empty((h, n, 4), np.uint8)
            bufd[:, :, 0] = dim[:, :, 2]; bufd[:, :, 1] = dim[:, :, 1]
            bufd[:, :, 2] = dim[:, :, 0]; bufd[:, :, 3] = 255
            imgD = QImage(bufd.tobytes(), n, h, QImage.Format_RGB32)
            self._bright = QPixmap.fromImage(imgB.copy())
            self._dim = QPixmap.fromImage(imgD.copy())
            self._pos = 0.0; self.update()
        except Exception:
            self._bright = self._dim = None; self.update()

    def clear(self):
        self._bright = self._dim = None; self._pos = 0.0; self.update()

    def set_envelope(self, _env):
        pass

    def set_pos(self, frac):
        self._pos = max(0.0, min(1.0, frac)); self.update()

    def _frac(self, x):
        return max(0.0, min(1.0, x / max(1, self.width())))

    def mousePressEvent(self, e):
        self.seek.emit(self._frac(e.x()))

    def mouseMoveEvent(self, e):
        self.seek.emit(self._frac(e.x()))

    def paintEvent(self, _):
        from PySide6.QtGui import QPainter
        from PySide6.QtCore import QRect
        if self._bright is None:
            return
        p = QPainter(self)
        w, h = self.width(), self.height()
        played = int(self._pos * w)
        # full spectrogram scaled to the widget, dimmed; bright copy clipped to played
        p.drawPixmap(QRect(0, 0, w, h), self._dim)
        if played > 0:
            p.save()
            p.setClipRect(QRect(0, 0, played, h))
            p.drawPixmap(QRect(0, 0, w, h), self._bright)
            p.restore()
        _draw_playhead_caret(p, played, w, h)


class WaveformBar(QWidget):
    """Filled amplitude-envelope seekbar: grey base, blue up to the playhead.
    Click/drag to seek. Mirrors the Tk app's _draw_wave (not bars — a filled graph)."""
    seek = Signal(float)             # 0..1 fraction

    GREY = "#c2c2c2"; BLUE = "#2d7dff"; LINE = "#1a1a1a"

    def __init__(self):
        super().__init__()
        self._env = []                   # 0..1 amplitude buckets
        self._pos = 0.0                  # 0..1 playhead
        self.setMinimumWidth(200); self.setFixedHeight(30)

    def set_envelope(self, env):
        self._env = env or []; self._pos = 0.0; self.update()

    def clear(self):
        """Blank the bar immediately (e.g. on song change, before the new waveform is
        ready) so the previous song's envelope doesn't linger."""
        self._env = []; self._pos = 0.0; self.update()

    def set_pos(self, frac):
        self._pos = max(0.0, min(1.0, frac)); self.update()

    def _frac(self, x):
        return max(0.0, min(1.0, x / max(1, self.width())))

    def mousePressEvent(self, e):
        self.seek.emit(self._frac(e.x()))

    def mouseMoveEvent(self, e):
        self.seek.emit(self._frac(e.x()))

    def paintEvent(self, _):
        from PySide6.QtGui import QPainter, QColor, QPolygonF
        from PySide6.QtCore import QPointF
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        w, h = self.width(), self.height(); mid = h / 2
        env = self._env
        if not env:
            return
        n = len(env)
        played_x = self._pos * w
        cols = []
        for i, a in enumerate(env):
            x = (i / (n - 1) * w) if n > 1 else 0.0
            amp = a * (mid - 2)
            cols.append((x, mid - amp, mid + amp))
        def fill(lo, hi, color):
            seg = [c for c in cols if lo <= c[0] <= hi]
            if len(seg) < 2:
                return
            pts = [QPointF(x, t) for x, t, b in seg] + \
                  [QPointF(x, b) for x, t, b in reversed(seg)]
            p.setPen(Qt.NoPen); p.setBrush(QColor(color)); p.drawPolygon(QPolygonF(pts))
        fill(0, w, self.GREY)
        if played_x > 0:
            fill(0, played_x, self.BLUE)
        _draw_playhead_caret(p, played_x, w, h)


class VolumeTriangle(QWidget):
    """Horizontal triangle (thin left, tall right) that fills blue over grey to the
    current level. Click/drag to set. Mirrors the Tk app's _draw_vol."""
    changed = Signal(float)          # 0..1

    GREY = "#c2c2c2"; BLUE = "#2d7dff"; LINE = "#1a1a1a"

    def __init__(self):
        super().__init__()
        self._level = 1.0
        self.setFixedSize(110, 28)

    def level(self):
        return self._level

    def set_level(self, lv):
        """Set the level programmatically (media keys) and notify listeners."""
        self._level = max(0.0, min(1.0, float(lv)))
        self.update(); self.changed.emit(self._level)

    def _set_from_x(self, x):
        self._level = max(0.0, min(1.0, x / max(1, self.width())))
        self.update(); self.changed.emit(self._level)

    def mousePressEvent(self, e):
        self._set_from_x(e.x())

    def mouseMoveEvent(self, e):
        self._set_from_x(e.x())

    def paintEvent(self, _):
        from PySide6.QtGui import QPainter, QColor, QPolygonF
        from PySide6.QtCore import QPointF
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        w, h = self.width(), self.height(); base = h - 2
        def tri(x_to, color):
            if x_to <= 0:
                return
            y_at = base - (x_to / w) * (base - 2)
            poly = QPolygonF([QPointF(0, base), QPointF(x_to, base), QPointF(x_to, y_at)])
            p.setPen(Qt.NoPen); p.setBrush(QColor(color)); p.drawPolygon(poly)
        tri(w, self.GREY)
        tri(self._level * w, self.BLUE)


def _version_tuple(v):
    """Parse a version string like 'v2.3.8' or '2.3.10' into a comparable tuple of ints.
    Strips a leading 'v' and any pre-release suffix; non-numeric parts become 0 so a
    malformed tag can never crash the comparison."""
    v = (v or "").strip().lstrip("vV")
    # keep only the leading dotted-number part (drop '-beta', '+build', etc.)
    import re as _re
    m = _re.match(r"\d+(?:\.\d+)*", v)
    if not m:
        return (0,)
    return tuple(int(x) for x in m.group(0).split("."))


def _is_newer_version(latest, current):
    """True if `latest` is a strictly newer version than `current`. Tuple compare with
    zero-padding so 2.3.10 > 2.3.9 (a string compare would get that wrong)."""
    lt, ct = _version_tuple(latest), _version_tuple(current)
    n = max(len(lt), len(ct))
    lt += (0,) * (n - len(lt)); ct += (0,) * (n - len(ct))
    return lt > ct


class UpdateChecker(QThread):
    """Checks GitHub's Releases API for a newer version, once, in the background at
    startup. Emits update_available(latest_tag) only if the latest release is strictly
    newer than APP_VERSION. Entirely fail-safe: any network/parse error is swallowed and
    NO signal is emitted, so the app behaves exactly as before when offline or
    rate-limited. Uses the Releases API (not tags) — the method most desktop apps use,
    since a release is a deliberate publish event and its tag_name maps to APP_VERSION."""
    update_available = Signal(str)      # latest tag, e.g. "v2.4.0"

    API_URL = "https://api.github.com/repos/nyannurs/BMS-Renderer/releases/latest"

    def run(self):
        try:
            import json, urllib.request
            from bms_core import APP_VERSION
            req = urllib.request.Request(
                self.API_URL,
                headers={"Accept": "application/vnd.github+json",
                         "User-Agent": "BMS-Renderer"})
            with urllib.request.urlopen(req, timeout=6) as r:
                data = json.loads(r.read().decode("utf-8", "replace"))
            tag = data.get("tag_name") or ""
            if tag and _is_newer_version(tag, APP_VERSION):
                self.update_available.emit(tag)
        except Exception:
            pass                            # offline / rate-limited / parse error → no-op


class RenderWorker(QThread):
    log = Signal(str)
    item_done = Signal(int)
    done = Signal()

    def __init__(self, items, out_dir, fmt, workers, cover_cfg=None,
                 quality=None, priority="Normal"):
        super().__init__()
        self.items, self.out_dir, self.fmt, self.workers = items, out_dir, fmt, workers
        self.cover_cfg = cover_cfg      # None | "__BLACK__" | path to whole-queue art
        self.quality = quality          # None = current default encode settings
        self.priority = priority
        self._abort = False             # set by abort() to stop after the current item

    def abort(self):
        self._abort = True

    def _resolve_cover(self, item):
        from bms_core import process_cover, _PIL_OK
        cfg = self.cover_cfg
        if cfg == "__BLACK__":
            return _black_cover_bytes()
        # per-song art (set via the picker / "assign black square") takes effect when
        # no whole-queue cover is set
        per = item.get("art")
        if not cfg and per == "__BLACK__":
            return _black_cover_bytes()
        path = cfg if cfg else per
        if path and path != "__BLACK__" and os.path.isfile(path) and _PIL_OK:
            try:
                data, _sz, _q = process_cover(path)
                return data
            except Exception:
                return None
        return None

    def run(self):
        try:
            self.setPriority(QThread.LowestPriority)
        except Exception:
            pass
        _apply_process_priority(self.priority)
        ext = {"FLAC": ".flac", "WAV": ".wav", "OGG": ".ogg", "MP3": ".mp3"}.get(self.fmt, ".flac")
        ff = ffmpeg_path() if self.fmt in ("OGG", "MP3", "FLAC") else None
        jobs = {}
        for row, it in enumerate(self.items):
            title = it["tags"].get("Title", "untitled")
            safe = _safe_output_stem(title)
            jobs[(it["path"], os.path.join(self.out_dir, safe + ext))] = (row, it)
        total = len(jobs); done = 0
        self.log.emit(f"Rendering {total} song(s) with {self.workers} worker process(es)…")
        # Use a 'spawn' context for the pool. On Linux the default 'fork' duplicates
        # the whole Qt/X11 application state into each worker, which causes segfaults
        # when workers or the app tear down — fresh 'spawn' interpreters avoid that.
        import multiprocessing as _mp
        ctx = _mp.get_context("spawn")
        ex = ProcessPoolExecutor(max_workers=self.workers, mp_context=ctx)
        try:
            futs = {ex.submit(render_one_job,
                              (p, o, self.fmt, it["tags"], self._resolve_cover(it), ff,
                               bms_core._LIBRARY_ROOT, self.quality)): (row, it)
                    for (p, o), (row, it) in jobs.items()}
            for fut in as_completed(futs):
                if self._abort:
                    break
                row, it = futs[fut]; done += 1
                try:
                    out_path, title, err = fut.result()
                except Exception as e:
                    self.log.emit(f"  [{done}/{total}] worker crashed: {e}"); continue
                if err:
                    self.log.emit(f"  [{done}/{total}] FAILED: {title}")
                else:
                    self.log.emit(f"  [{done}/{total}] done -> {out_path}")
                    self.item_done.emit(row)
        finally:
            if self._abort:
                # Hard-stop: cancel not-yet-started futures AND terminate the worker
                # PROCESSES that are mid-render — shutdown(wait=False) alone leaves
                # in-flight renders running to completion in the background.
                for f in futs:
                    f.cancel()
                self._kill_pool(ex)
                self.log.emit("Render aborted.")
            else:
                ex.shutdown(wait=True)
                self.log.emit("Queue render complete.")
        self.done.emit()

    @staticmethod
    def _kill_pool(ex):
        """Terminate a ProcessPoolExecutor's worker processes immediately, so an
        aborted render doesn't keep rendering in the background."""
        procs = list(getattr(ex, "_processes", {}).values())
        for p in procs:
            try:
                p.terminate()
            except Exception:
                pass
        # don't wait on the children (we just killed them); tear down the executor's
        # bookkeeping without blocking
        try:
            ex.shutdown(wait=False, cancel_futures=True)
        except TypeError:
            ex.shutdown(wait=False)        # older Python without cancel_futures
        for p in procs:
            try:
                p.join(timeout=2)
                if p.is_alive():
                    p.kill()               # SIGKILL anything still standing
            except Exception:
                pass


