    def _load_playlists(self):
        self._playlists = load_playlists()
        self.pl_pick.blockSignals(True)
        self.pl_pick.clear()
        self.pl_pick.addItems(sorted(self._playlists.keys()))
        self.pl_pick.blockSignals(False)
        if self._playlists:
            self._show_playlist(self.pl_pick.currentText())
        else:
            self.pltree.clear(); self.pl_count.setText("No playlists yet")

    def _pl_resolve(self, entry):
        """Resolve a playlist entry {md5,...} to the owned song dict, or None."""
        if not isinstance(entry, dict):
            return None
        return getattr(self, "_md5_index", {}).get(entry.get("md5"))

    def _show_playlist(self, name=None):
        name = name or self.pl_pick.currentText()
        self.pltree.clear()
        entries = self._playlists.get(name, [])
        owned = 0
        for ei, entry in enumerate(entries):
            # "Added" cell: show a human date, sort by the raw timestamp. Entries saved
            # before this column existed have no "added" field — fall back to their
            # position in the list (insertion order == the order they were added), so
            # old playlists still sort oldest→newest sensibly.
            ts = entry.get("added") if isinstance(entry, dict) else None
            sort_ts = ts if ts is not None else ei
            added_txt = self._fmt_added(ts)
            s = self._pl_resolve(entry)
            if s:
                item = _NumericTreeItem([s.get("title",""), s.get("artist",""),
                                        s.get("mode",""), str(s.get("notes","")), added_txt])
                item.setData(0, Qt.UserRole, s["path"])
                item.setData(4, _NumericTreeItem.SORTKEY_ROLE, float(sort_ts))
                owned += 1
            else:
                # entry not owned on this machine — show greyed with saved title
                item = QTreeWidgetItem([entry.get("title","?"), entry.get("artist",""),
                                        "—", "(not owned)", added_txt])
                item.setForeground(0, Qt.gray)
            # remember which playlist entry this row IS, so selection stays correct
            # after the user sorts a column (tree row order != entries order).
            item.setData(0, Qt.UserRole + 1, ei)
            self.pltree.addTopLevelItem(item)
        self.pl_count.setText(f"{len(entries)} songs ({owned} owned)")

    @staticmethod
    def _fmt_added(ts):
        """Render an added-timestamp as a short local date, or '—' when unknown."""
        if ts is None:
            return "—"
        try:
            import datetime
            return datetime.datetime.fromtimestamp(float(ts)).strftime("%Y-%m-%d")
        except (ValueError, TypeError, OSError):
            return "—"

    def _pl_new(self):
        from PySide6.QtWidgets import QInputDialog
        name, ok = QInputDialog.getText(self, "New playlist", "Playlist name:")
        if not ok or not name.strip():
            return
        name = name.strip()
        if name in self._playlists:
            self.log(f"Playlist '{name}' already exists."); return
        self._playlists[name] = []
        save_one_playlist(name, [])
        self.pl_pick.addItem(name); self.pl_pick.setCurrentText(name)
        self.log(f"Created playlist '{name}'.")

    def _pl_rename(self):
        from PySide6.QtWidgets import QInputDialog
        old = self.pl_pick.currentText()
        if not old:
            return
        new, ok = QInputDialog.getText(self, "Rename playlist", "New name:", text=old)
        if not ok or not new.strip() or new.strip() == old:
            return
        new = new.strip()
        if new in self._playlists:
            self.log(f"Playlist '{new}' already exists."); return
        self._playlists[new] = self._playlists.pop(old)
        save_one_playlist(new, self._playlists[new]); delete_playlist_file(old)
        self._load_playlists(); self.pl_pick.setCurrentText(new)
        self.log(f"Renamed '{old}' → '{new}'.")

    def _pl_delete(self):
        name = self.pl_pick.currentText()
        if not name:
            return
        if QMessageBox.question(self, "Delete playlist",
                                f"Delete playlist '{name}'? This can't be undone.") \
                != QMessageBox.Yes:
            return
        self._playlists.pop(name, None); delete_playlist_file(name)
        self._load_playlists()
        self.log(f"Deleted playlist '{name}'.")

    def _pl_selected_songs(self):
        name = self.pl_pick.currentText()
        entries = self._playlists.get(name, [])
        out = []
        for it in self.pltree.selectedItems():
            i = it.data(0, Qt.UserRole + 1)         # entry index (sort-safe)
            base = getattr(self, "_path_index", {}).get(it.data(0, Qt.UserRole))
            if not base:
                continue
            s = dict(base)
            if i is not None and 0 <= i < len(entries) and isinstance(entries[i], dict) \
                    and isinstance(entries[i].get("tags"), dict):
                s["tags"] = entries[i]["tags"]      # carry edited tags (incl. Album)
            out.append(s)
        return out

    def _on_pl_select(self):
        items = self.pltree.selectedItems()
        if not items:
            return
        # Map the selected row back to its playlist entry by the index we stored on the
        # item, NOT its position in the tree — the tree is sortable, so row order no
        # longer matches the entries list after the user clicks a column header.
        i = items[0].data(0, Qt.UserRole + 1)
        name = self.pl_pick.currentText()
        entries = self._playlists.get(name, [])
        if i is None or not (0 <= i < len(entries)):
            return
        entry = entries[i]
        s = self._pl_resolve(entry)
        # editable tags: use the entry's saved tags if present, else defaults
        if isinstance(entry, dict) and entry.get("tags"):
            tags = dict(entry["tags"])
        elif s:
            tags = self._default_tags(s)
        else:
            tags = {"Title": entry.get("title", ""), "Artist": entry.get("artist", "")}
        self._bind_tags("playlist", i, tags)            # set selection first
        if s: self._show_info(s)

    def _on_pl_double(self, item, _col):
        if self._rmb_down():
            return
        # Start playback from this row's VISUAL position so auto-advance walks the
        # list top-to-bottom as displayed. (Selection/tags still use the entry index
        # via _on_pl_select; only the play cursor is row-based.)
        row = self.pltree.indexOfTopLevelItem(item)
        s = getattr(self, "_path_index", {}).get(item.data(0, Qt.UserRole))
        if s:
            self._start_song(s["path"], s.get("title", "?"), "playlist", row)

    def _pl_remove(self):
        name = self.pl_pick.currentText()
        if not name:
            return
        rows = sorted({it.data(0, Qt.UserRole + 1)
                       for it in self.pltree.selectedItems()
                       if it.data(0, Qt.UserRole + 1) is not None}, reverse=True)
        entries = self._playlists.get(name, [])
        for r in rows:
            if 0 <= r < len(entries):
                entries.pop(r)
        save_one_playlist(name, entries)
        self._show_playlist(name)

    def _pl_render(self):
        name = self.pl_pick.currentText()
        if not name or not self._playlists.get(name):
            QMessageBox.information(self, "Empty", "This playlist has no songs."); return
        out_dir = self.out_edit.text() or load_config().get("output")
        if not out_dir or not os.path.isdir(out_dir):
            QMessageBox.information(self, "No output folder", "Choose an output folder first."); return
        items = self._pl_collect_items()
        if not items:
            self.log("No owned songs in this playlist to render."); return
        dlg = AudioExportDialog(self, self.pl_fmt.currentText(),
                                self.pl_threads.value(), self.pl_threads.maximum())
        if dlg.exec() != QDialog.Accepted:
            return
        fmt, threads, quality, priority = dlg.result_settings()
        # keep the (hidden) playlist controls in sync, which propagates to the Queue tab
        self.pl_fmt.setCurrentText(fmt)
        self.pl_threads.setValue(threads)
        self.pl_render_btn.setEnabled(False)
        # apply the assigned "Album art (whole queue)" cover to every rendered track,
        # exactly like the Queue render does — without this the playlist render ignored
        # the assigned cover and each FLAC kept its own per-song art (bug).
        cover_cfg = ("__BLACK__" if self._art_black else (self._art_path or None))
        self._pl_worker = RenderWorker(items, out_dir, fmt, threads,
                                       cover_cfg, quality=quality, priority=priority)
        prog = RenderProgressDialog(self, "Rendering Playlist", len(items))
        self._pl_worker.log.connect(self.log)
        self._pl_worker.item_done.connect(lambda _row: prog.step())
        self._pl_worker.done.connect(prog.finish)
        prog.aborted.connect(self._pl_worker.abort)
        self._pl_worker.done.connect(lambda: self.pl_render_btn.setEnabled(True))
        self._pl_worker.start()
        prog.exec()

    def _pl_collect_items(self):
        """Owned songs of the current playlist as render items (path + merged tags),
        in the playlist's saved order. Shared by audio and BGA render."""
        name = self.pl_pick.currentText()
        items = []
        for e in self._playlists.get(name, []):
            s = self._pl_resolve(e)
            if not s:
                continue
            tags = {"Title": s.get("title", ""), "Artist": s.get("artist", ""),
                    "Album": "", "AlbumArtist": "",
                    "Genre": s.get("genre", ""), "BPM": str(s.get("bpm", ""))}
            if isinstance(e, dict) and isinstance(e.get("tags"), dict):
                for k, v in e["tags"].items():
                    tags[k] = v
            items.append({"path": s["path"], "tags": tags,
                          "art": e.get("art") if isinstance(e, dict) else None})
        return items

    def _pl_render_bga(self):
        name = self.pl_pick.currentText()
        if not name or not self._playlists.get(name):
            QMessageBox.information(self, "Empty", "This playlist has no songs."); return
        out_dir = self.out_edit.text() or load_config().get("output")
        if not out_dir or not os.path.isdir(out_dir):
            QMessageBox.information(self, "No output folder", "Choose an output folder first."); return
        if not ffmpeg_path():
            QMessageBox.information(self, "ffmpeg required", "BGA video export needs ffmpeg on PATH."); return
        items = self._pl_collect_items()
        if not items:
            self.log("No owned songs in this playlist to render."); return
        dlg = BGAExportDialog(self, default_threads=self.pl_threads.value())
        if dlg.exec() != QDialog.Accepted:
            return
        opts, priority, threads = dlg.options()
        self.pl_bga_btn.setEnabled(False)
        self._pl_bga_worker = BGAWorker(items, out_dir, threads,
                                        encode_opts=opts, priority=priority)
        prog = RenderProgressDialog(self, "Rendering BGA Videos", len(items))
        self._pl_bga_worker.log.connect(self.log)
        self._pl_bga_worker.total_known.connect(prog.set_total)
        self._pl_bga_worker.item_done.connect(prog.set_value)
        self._pl_bga_worker.done.connect(prog.finish)
        prog.aborted.connect(self._pl_bga_worker.abort)
        self._pl_bga_worker.done.connect(lambda: self.pl_bga_btn.setEnabled(True))
        self._pl_bga_worker.start()
        prog.exec()

    def _pl_context_menu(self, pos):
        item = self.pltree.itemAt(pos)
        if not item:
            return
        # gather the full selection (resolved owned songs)
        sel = self._pl_selected_songs()
        n = len(sel)
        from PySide6.QtWidgets import QMenu
        m = QMenu(self)
        act_play = m.addAction("Play") if n == 1 else None
        act_queue = m.addAction(f"Add {n} selected to Queue" if n > 1 else "Add to Queue") if sel else None
        # send to ANOTHER playlist (the previously-missing feature) — excludes current
        cur = self.pl_pick.currentText()
        send_menu = m.addMenu(f"Send {n} selected to playlist" if n > 1 else "Send to playlist") if sel else None
        send_actions = {}
        if send_menu is not None:
            for name in sorted(getattr(self, "_playlists", {})):
                if name == cur:
                    continue
                send_actions[send_menu.addAction(name)] = name
            send_menu.addSeparator()
            send_new = send_menu.addAction("New playlist…")
        else:
            send_new = None
        m.addSeparator()
        act_rm = m.addAction("Remove from Playlist")
        chosen = m.exec(self.pltree.viewport().mapToGlobal(pos))
        if chosen is None:
            return
        if chosen == act_rm:
            self._pl_remove()
        elif sel and chosen == act_play:
            self._play_song(sel[0], kind="playlist")
        elif sel and chosen == act_queue:
            self._enqueue_songs(sel)
        elif sel and chosen == send_new:
            self._add_songs_new_playlist(sel)
        elif chosen in send_actions:
            self._add_songs_to_playlist(sel, send_actions[chosen])

