    def _load_tables_list(self):
        if not os.path.exists(TABLES_PATH):
            save_tables_file([])
        self._table_defs = load_tables_file()
        self.table_pick.blockSignals(True)
        self.table_pick.clear()
        self.table_pick.addItems([t.get("name", t.get("url", "?")) for t in self._table_defs])
        self.table_pick.blockSignals(False)
        self.table_status.setText(f"{len(self._table_defs)} table(s)" if self._table_defs
                                  else "No tables — use 'Add table by URL…'")
        if self._table_defs:
            self._on_table_pick(self.table_pick.currentText())

    def _add_table_by_url(self):
        from PySide6.QtWidgets import QInputDialog
        url, ok = QInputDialog.getText(self, "Add table", "Paste the difficulty-table URL:")
        if not ok or not url.strip():
            return
        url = url.strip()
        if any(t.get("url") == url for t in self._table_defs):
            self.table_status.setText("That table URL is already in the list."); return
        self.table_status.setText("Fetching table…")
        self._park_worker(getattr(self, "_tfetch", None))
        self._tfetch = TableFetchWorker(url)
        self._tfetch.log.connect(self.log)
        self._tfetch.fetched.connect(self._on_table_added)
        self._tfetch.start()

    def _on_table_added(self, url, tbl, err):
        if err or tbl is None:
            self.table_status.setText("Couldn't fetch that table."); self.log(f"Table error: {err}")
            return
        name = tbl.get("name") or url
        existing = {t.get("name") for t in self._table_defs}
        final = name; n = 2
        while final in existing:
            final = f"{name} ({n})"; n += 1
        self._table_defs.append({"name": final, "url": url})
        save_tables_file(self._table_defs)
        self._table_cache[final] = tbl
        self.table_pick.addItem(final); self.table_pick.setCurrentText(final)
        self.log(f"Added '{final}' ({len(tbl.get('entries', []))} entries)")

    def _park_worker(self, wkr):
        """Keep a reference to a QThread that's being superseded so it can't be garbage-
        collected while still running — a QThread destroyed mid-run aborts the whole
        process in PySide6. Parked workers are dropped once they've finished. Used where
        a worker attribute is about to be overwritten by a new one (rapid re-triggers)."""
        if wkr is None:
            return
        parked = getattr(self, "_parked_workers", None)
        if parked is None:
            parked = self._parked_workers = []
        # drop any that have finished, keep the still-running ones (incl. the new park)
        self._parked_workers = [w for w in parked if w.isRunning()]
        if wkr.isRunning():
            self._parked_workers.append(wkr)

    def _on_table_pick(self, name):
        if not name:
            return
        if name in self._table_cache:
            self._render_table(self._table_cache[name]); return
        tdef = next((t for t in self._table_defs if t.get("name") == name), None)
        if not tdef or "example.com" in tdef.get("url", ""):
            self.table_status.setText("Edit tables.json with a real URL first."); return
        self.table_status.setText(f"Loading {name}…")
        self._park_worker(getattr(self, "_tfetch2", None))
        self._tfetch2 = TableFetchWorker(tdef["url"])
        self._tfetch2.log.connect(self.log)
        self._tfetch2.fetched.connect(lambda u, t, e, nm=name: self._on_table_loaded(nm, t, e))
        self._tfetch2.start()

    def _on_table_loaded(self, name, tbl, err):
        if err or tbl is None:
            self.table_status.setText(f"Failed to load {name}"); return
        self._table_cache[name] = tbl
        self._render_table(tbl)

    def _refresh_table(self):
        name = self.table_pick.currentText()
        self._table_cache.pop(name, None)
        self._on_table_pick(name)

    def _render_table(self, tbl):
        self.ttree.clear()
        idx = getattr(self, "_md5_index", {})
        by_level = {}
        for e in tbl.get("entries", []):
            by_level.setdefault(e.get("level", "?"), []).append(e)
        def level_key(lv):
            try: return (0, float(lv))
            except (ValueError, TypeError): return (1, str(lv))
        sym = tbl.get("symbol", "")
        owned_total = 0
        self._tbl_play_order = []        # flat owned-song order for next/prev
        for order_i, lv in enumerate(sorted(by_level.keys(), key=level_key)):
            # The level parent sorts by DIFFICULTY, not by the "★10" text (which would
            # put ★10 before ★2). We store a numeric sort key on column 0: numeric
            # levels by value, non-numeric ones (e.g. "???") after all numbers. Using a
            # _NumericTreeItem + SORTKEY_ROLE means column-0 sorting respects difficulty
            # even though the cell shows "★10".
            kind, val = level_key(lv)
            sort_val = float(val) if kind == 0 else 1e9 + order_i
            parent = _NumericTreeItem([f"{sym}{lv}", "", "", "", ""])
            parent.setData(0, _NumericTreeItem.SORTKEY_ROLE, sort_val)
            for e in by_level[lv]:
                s = idx.get(e.get("md5"))           # only owned charts have a match
                if not s:
                    continue
                child = _NumericTreeItem(self._row_vals(s))
                child.setData(0, Qt.UserRole, s["path"])
                parent.addChild(child); owned_total += 1
                self._tbl_play_order.append(s)
            if parent.childCount() > 0:
                self.ttree.addTopLevelItem(parent); parent.setExpanded(True)
        self.table_status.setText(
            f"{tbl.get('name','')}: {owned_total} owned of {len(tbl.get('entries', []))}")
        # if album view is active, refresh it too (it reads from the tree we just built)
        if hasattr(self, "t_album") and self.t_album.isChecked():
            self._populate_collapsible(self.t_grid, self._table_level_sections())

    def _table_selected_songs(self):
        out = []
        # Album view: selections live in the per-level tile grids, not the tree.
        # Gather from every section grid (shift/ctrl-click spans levels).
        if getattr(self, "t_album", None) is not None and self.t_album.isChecked():
            seen = set()
            for grid, _n in getattr(self.t_grid, "_sections", []):
                for it in grid.selectedItems():
                    p = it.data(Qt.UserRole)
                    if p in seen:
                        continue
                    seen.add(p)
                    s = getattr(self, "_path_index", {}).get(p)
                    if s:
                        out.append(s)
            return out
        # List view: read the tree selection.
        for it in self.ttree.selectedItems():
            p = it.data(0, Qt.UserRole)
            s = getattr(self, "_path_index", {}).get(p)
            if s:
                out.append(s)
        return out

    def _on_table_select(self):
        sel = self._table_selected_songs()
        if len(sel) != 1:
            return
        self._sel_kind, self._sel_index = None, None
        self._show_info(sel[0]); self._show_readonly_tags(sel[0])

    def _on_table_double(self, item, _col):
        if self._rmb_down():
            return
        p = item.data(0, Qt.UserRole)
        s = getattr(self, "_path_index", {}).get(p)
        if s:
            order = getattr(self, "_tbl_play_order", [])
            idx = next((i for i, x in enumerate(order) if x["path"] == s["path"]), -1)
            self._start_song(s["path"], s.get("title", "?"), "table", idx)

    def _table_add_all(self):
        songs = []
        for i in range(self.ttree.topLevelItemCount()):
            parent = self.ttree.topLevelItem(i)
            for j in range(parent.childCount()):
                p = parent.child(j).data(0, Qt.UserRole)
                s = getattr(self, "_path_index", {}).get(p)
                if s: songs.append(s)
        self._enqueue_songs(songs)

    def _table_add_selected(self):
        self._enqueue_songs(self._table_selected_songs())

